"""The `stockroom` command."""

import csv
import io
import json
import os
import sys

from . import orders as orders_mod
from . import shelves
from .parsing import (
    ParseError,
    Movement,
    parse_catalog,
    parse_date_text,
    parse_movements,
    parse_orders,
    to_int,
)
from .pricing import money, price_order

USAGE = (
    "usage: stockroom [--dir DIR] COMMAND [ARGS]\n"
    "  stock [--json] | low [--json] | history SKU [--json]\n"
    "  receive DATE SKU QUANTITY [NOTE] | ship DATE SKU QUANTITY [NOTE]\n"
    "  quote ORDER [--json] | fulfil ORDER DATE | invoice ORDER [--json]\n"
    "  report [--format text|csv|json]"
)

CATALOG, MOVEMENTS, ORDERS = "catalog.txt", "movements.txt", "orders.txt"

# command -> (files read, positional args (min, max), takes --json, takes --format, raw arguments)
COMMANDS = {
    "stock": ((CATALOG, MOVEMENTS), (0, 0), True, False, False),
    "low": ((CATALOG, MOVEMENTS), (0, 0), True, False, False),
    "history": ((CATALOG, MOVEMENTS), (1, 1), True, False, False),
    "receive": ((CATALOG, MOVEMENTS), (3, 4), False, False, True),
    "ship": ((CATALOG, MOVEMENTS), (3, 4), False, False, True),
    "quote": ((CATALOG, ORDERS), (1, 1), True, False, False),
    "fulfil": ((CATALOG, MOVEMENTS, ORDERS), (2, 2), False, False, True),
    "invoice": ((CATALOG, MOVEMENTS, ORDERS), (1, 1), True, False, False),
    "report": ((CATALOG, MOVEMENTS, ORDERS), (0, 0), False, True, False),
}


class Usage(Exception):
    """Something wrong with the command line (exit 2)."""


class Unreadable(Exception):
    """A file cannot be read or written (exit 2)."""


class Refused(Exception):
    """A data mistake or a refused request (exit 1)."""


def _json(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def _lines(rows) -> str:
    return "".join(row + "\n" for row in rows)


# ---------------------------------------------------------------- command line


def _split_dir(argv):
    """Pull `--dir` out of the arguments; returns (directory or None, the rest)."""
    directory = None
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise Usage("option --dir needs a value")
            directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            directory = arg[len("--dir="):]
            i += 1
            continue
        rest.append(arg)
        i += 1
    if directory == "":
        raise Usage("bad value for --dir: empty")
    return directory, rest


def _parse_command_line(argv):
    directory, rest = _split_dir(argv)
    if not rest:
        raise Usage("no command given")
    name = rest[0]
    if name not in COMMANDS:
        raise Usage("unknown option %s" % name if name.startswith("-") else "unknown command %s" % name)
    _, (low, high), takes_json, takes_format, raw = COMMANDS[name]
    args = rest[1:]
    positional = []
    as_json = False
    fmt = "text"
    i = 0
    while i < len(args):
        arg = args[i]
        i += 1
        if raw or not arg.startswith("-"):
            positional.append(arg)
        elif arg == "--json" and takes_json:
            as_json = True
        elif takes_format and (arg == "--format" or arg.startswith("--format=")):
            if arg == "--format":
                if i >= len(args):
                    raise Usage("option --format needs a value")
                fmt = args[i]
                i += 1
            else:
                fmt = arg[len("--format="):]
            if fmt not in ("text", "csv", "json"):
                raise Usage("bad value for --format: %r (text, csv or json)" % fmt)
        else:
            raise Usage("unknown option %s" % arg)
    if not low <= len(positional) <= high:
        raise Usage("wrong number of arguments for %s" % name)
    when = None
    if name in ("receive", "ship"):
        when = parse_date_text(positional[0])
    elif name == "fulfil":
        when = parse_date_text(positional[1])
    if name in ("receive", "ship", "fulfil") and when is None:
        raise Usage("bad date %r" % positional[0 if name != "fulfil" else 1])
    return name, directory, positional, as_json, fmt, when


# ----------------------------------------------------------------------- files


def _read_files(directory, names):
    base = directory if directory is not None else os.curdir
    if not os.path.isdir(base):
        raise Unreadable("%s: not a directory" % base)
    texts = {}
    raw = {}
    for name in names:
        path = os.path.join(base, name)
        try:
            with open(path, "rb") as handle:
                data = handle.read()
        except FileNotFoundError:
            if name == CATALOG:
                raise Unreadable("%s: file not found" % name)
            data = b""
        except OSError as exc:
            raise Unreadable("%s: %s" % (name, exc.strerror or exc))
        try:
            texts[name] = data.decode("utf-8")
        except UnicodeDecodeError:
            raise Unreadable("%s: not valid UTF-8" % name)
        raw[name] = data
    return base, texts, raw


def _parse_files(texts):
    data = {}
    try:
        name = CATALOG
        data["catalog"] = parse_catalog(texts[CATALOG])
        if MOVEMENTS in texts:
            name = MOVEMENTS
            data["movements"] = parse_movements(texts[MOVEMENTS], data["catalog"])
        if ORDERS in texts:
            name = ORDERS
            data["orders"] = parse_orders(texts[ORDERS], data["catalog"])
    except ParseError as exc:
        raise Refused("%s: %s" % (name, exc))
    return data


def _append(base, raw_existing, text):
    prefix = b"\n" if raw_existing and not raw_existing.endswith(b"\n") else b""
    try:
        with open(os.path.join(base, MOVEMENTS), "ab") as handle:
            handle.write(prefix + text.encode("utf-8"))
    except OSError as exc:
        raise Unreadable("%s: %s" % (MOVEMENTS, exc.strerror or exc))


# -------------------------------------------------------------------- commands


def _find_order(data, name):
    wanted = name.upper()
    for order in data["orders"]:
        if order.id == wanted:
            return order
    raise Refused("unknown order %s" % name)


def _cmd_stock(data, as_json):
    levels = shelves.stock_levels(data["catalog"], data["movements"])
    rows = []
    for sku in sorted(data["catalog"]):
        product = data["catalog"][sku]
        rows.append((sku, product.name, levels[sku], shelves.status(levels[sku], product.reorder)))
    if as_json:
        return _json([{"sku": s, "name": n, "onhand": o, "status": st} for s, n, o, st in rows])
    return _lines("%s %d %s %s" % (s_, o, st, n) for s_, n, o, st in rows)


def _cmd_low(data, as_json):
    levels = shelves.stock_levels(data["catalog"], data["movements"])
    rows = []
    for sku in sorted(data["catalog"]):
        product = data["catalog"][sku]
        if shelves.status(levels[sku], product.reorder) != "ok":
            rows.append((sku, levels[sku], product.reorder, shelves.buy_quantity(levels[sku], product.reorder)))
    if as_json:
        return _json([{"sku": s, "onhand": o, "reorder": r, "buy": b} for s, o, r, b in rows])
    return _lines("%s %d %d %d" % row for row in rows)


def _cmd_history(data, as_json, args):
    sku = args[0].upper()
    if sku not in data["catalog"]:
        raise Refused("unknown SKU %s" % args[0])
    rows = shelves.history(sku, data["movements"])
    if as_json:
        return _json(
            [
                {"date": m.date.isoformat(), "delta": "%+d" % m.quantity, "balance": b, "note": m.note}
                for m, b in rows
            ]
        )
    return _lines(
        "%s %+d %d" % (m.date.isoformat(), m.quantity, b) + (" " + m.note if m.note else "") for m, b in rows
    )


def _cmd_move(name, data, args, when, base, raw_movements):
    sku = args[1].upper()
    if sku not in data["catalog"]:
        raise Refused("unknown SKU %s" % args[1])
    qty_text = args[2]
    if not (qty_text.isascii() and qty_text.isdigit()):
        raise Refused("bad quantity %r (a whole number of one or more)" % qty_text)
    try:
        quantity = to_int(qty_text, 0, "quantity")
    except ParseError:
        raise Refused("quantity %r is too large" % qty_text[:20])
    if quantity < 1:
        raise Refused("bad quantity %r (a whole number of one or more)" % qty_text)
    note = args[3].strip() if len(args) == 4 else ""
    if "\n" in note or "\r" in note:
        raise Refused("a note may not contain a line break")
    signed = quantity if name == "receive" else -quantity
    move = Movement(when, sku, signed, note)
    if shelves.breaks_stock(data["movements"], move):
        raise Refused("%s %d of %s on %s would take the stock below zero" % (name, quantity, sku, args[0]))
    line = shelves.format_movement(when, sku, signed, note)
    _append(base, raw_movements, line + "\n")
    return line + "\n"


def _quote_text(quote, prefix=""):
    rows = ["%s%s %s %s" % (prefix, quote.order, quote.date.isoformat(), quote.customer)]
    for ln in quote.lines:
        rows.append(
            "%s %d %s %s %s %s"
            % (ln.sku, ln.quantity, money(ln.unit), money(ln.gross), money(ln.discount), money(ln.net))
        )
    rows.append("subtotal " + money(quote.subtotal))
    rows.append("order discount " + money(quote.order_discount))
    rows.append("tax " + money(quote.tax))
    rows.append("total " + money(quote.total))
    return _lines(rows)


def _quote_json(quote):
    return {
        "order": quote.order,
        "date": quote.date.isoformat(),
        "customer": quote.customer,
        "lines": [
            {
                "sku": ln.sku,
                "quantity": ln.quantity,
                "unit": money(ln.unit),
                "gross": money(ln.gross),
                "discount": money(ln.discount),
                "net": money(ln.net),
            }
            for ln in quote.lines
        ],
        "subtotal": money(quote.subtotal),
        "order_discount": money(quote.order_discount),
        "tax": money(quote.tax),
        "total": money(quote.total),
    }


def _cmd_quote(data, as_json, args):
    quote = price_order(_find_order(data, args[0]), data["catalog"])
    return _json(_quote_json(quote)) if as_json else _quote_text(quote)


def _cmd_invoice(data, as_json, args):
    order = _find_order(data, args[0])
    shipped = orders_mod.invoice_order(order, orders_mod.shipped_index(data["movements"]))
    if shipped is None:
        raise Refused("nothing has shipped for %s" % order.id)
    quote = price_order(shipped, data["catalog"])
    return _json(_quote_json(quote)) if as_json else _quote_text(quote, "invoice ")


def _cmd_fulfil(data, args, when, base, raw_movements):
    order = _find_order(data, args[0])
    if when < order.date:
        raise Refused("%s is dated %s; cannot fulfil on %s" % (order.id, order.date.isoformat(), args[1]))
    index = orders_mod.shipped_index(data["movements"])
    sent = {sku: s for sku, _, s in orders_mod.shipped_lines(order, index)}
    plan = orders_mod.plan_fulfilment(order, data["movements"], when, index)
    added = [shelves.format_movement(when, sku, -n, "order " + order.id) for sku, _, n in plan if n > 0]
    rows = []
    after = []
    for (sku, owed, n), (_, qty) in zip(plan, order.lines):
        rows.append("%s shipped %d backordered %d" % (sku, n, owed - n))
        after.append((sku, qty, sent[sku] + n))
    rows.append("status " + orders_mod.status_of(after))
    if added:
        _append(base, raw_movements, "".join(line + "\n" for line in added))
    return _lines(rows)


def _cmd_report(data, fmt):
    rows = orders_mod.report_rows(data["orders"], data["catalog"], data["movements"])
    for row in rows:
        row["quoted"] = money(row["quoted"])
        row["invoiced"] = money(row["invoiced"])
    if fmt == "json":
        return _json(rows)
    if fmt == "csv":
        keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(keys)
        for row in rows:
            writer.writerow([row[k] for k in keys])
        return buffer.getvalue()
    return _lines(
        "%s %s %s %s %d/%d %s %s"
        % (r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
        for r in rows
    )


def _run(argv):
    name, directory, args, as_json, fmt, when = _parse_command_line(argv)
    files = COMMANDS[name][0]
    base, texts, raw = _read_files(directory, files)
    data = _parse_files(texts)
    data.setdefault("movements", [])
    data.setdefault("orders", [])
    if name == "stock":
        return _cmd_stock(data, as_json)
    if name == "low":
        return _cmd_low(data, as_json)
    if name == "history":
        return _cmd_history(data, as_json, args)
    if name in ("receive", "ship"):
        return _cmd_move(name, data, args, when, base, raw[MOVEMENTS])
    if name == "quote":
        return _cmd_quote(data, as_json, args)
    if name == "fulfil":
        return _cmd_fulfil(data, args, when, base, raw[MOVEMENTS])
    if name == "invoice":
        return _cmd_invoice(data, as_json, args)
    return _cmd_report(data, fmt)


# ------------------------------------------------------------------------ main


def _silence_stdout():
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def _emit(text):
    if not text:
        return 0
    try:
        sys.stdout.write(text)
        sys.stdout.flush()
    except BrokenPipeError:
        _silence_stdout()
    except OSError as exc:
        _silence_stdout()
        print("stockroom: cannot write output: %s" % (exc.strerror or exc), file=sys.stderr)
        return 2
    return 0


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    try:
        reconfigure = sys.stdout.reconfigure
    except AttributeError:
        reconfigure = None
    if reconfigure is not None:
        try:
            reconfigure(encoding="utf-8")
        except (ValueError, OSError):
            pass
    try:
        out = _run(list(argv))
    except Usage as exc:
        print("stockroom: %s\n%s" % (exc, USAGE), file=sys.stderr)
        return 2
    except Unreadable as exc:
        print("stockroom: %s" % exc, file=sys.stderr)
        return 2
    except Refused as exc:
        print("stockroom: %s" % exc, file=sys.stderr)
        return 1
    return _emit(out)

