content.content:
"""The `stockroom` command."""

import csv
import io
import json
import os
import sys

from . import orders as orders_mod
from . import shelves
from .parsing import (
    ParseError,
    Movement,
    parse_catalog,
    parse_date_text,
    parse_movements,
    parse_orders,
    to_int,
)
from .pricing import money, price_order

USAGE = (
    "usage: stockroom [--dir DIR] COMMAND [ARGS]\n"
    "  stock [--json] | low [--json] | history SKU [--json]\n"
    "  receive DATE SKU QUANTITY [NOTE] | ship DATE SKU QUANTITY [NOTE]\n"
    "  quote ORDER [--json] | fulfil ORDER DATE | invoice ORDER [--json]\n"
    "  report [--format text|csv|json]"
)

CATALOG, MOVEMENTS, ORDERS = "catalog.txt", "movements.txt", "orders.txt"

# command -> (files read, positional args (min, max), takes --json, takes --format, raw arguments)
COMMANDS = {
    "stock": ((CATALOG, MOVEMENTS), (0, 0), True, False, False),
    "low": ((CATALOG, MOVEMENTS), (0, 0), True, False, False),
    "history": ((CATALOG, MOVEMENTS), (1, 1), True, False, False),
    "receive": ((CATALOG, MOVEMENTS), (3, 4), False, False, True),
    "ship": ((CATALOG, MOVEMENTS), (3, 4), False, False, True),
    "quote": ((CATALOG, ORDERS), (1, 1), True, False, False),
    "fulfil": ((CATALOG, MOVEMENTS, ORDERS), (2, 2), False, False, True),
    "invoice": ((CATALOG, MOVEMENTS, ORDERS), (1, 1), True, False, False),
    "report": ((CATALOG, MOVEMENTS, ORDERS), (0, 0), False, True, False),
}


class Usage(Exception):
    """Something wrong with the command line (exit 2)."""


class Unreadable(Exception):
    """A file cannot be read or written (exit 2)."""


class Refused(Exception):
    """A data mistake or a refused request (exit 1)."""


def _json(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def _lines(rows) -> str:
    return "".join(row + "\n" for row in rows)


# ---------------------------------------------------------------- command line


def _split_dir(argv):
    """Pull `--dir` out of the arguments; returns (directory or None, the rest)."""
    directory = None
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise Usage("option --dir needs a value")
            directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            directory = arg[len("--dir="):]
            i += 1
            continue
        rest.append(arg)
        i += 1
    if directory == "":
        raise Usage("bad value for --dir: empty")
    return directory, rest


def _parse_command_line(argv):
    directory, rest = _split_dir(argv)
    if not rest:
        raise Usage("no command given")
    name = rest[0]
    if name not in COMMANDS:
        raise Usage("unknown option %s" % name if name.startswith("-") else "unknown command %s" % name)
    _, (low, high), takes_json, takes_format, raw = COMMANDS[name]
    args = rest[1:]
    positional = []
    as_json = False
    fmt = "text"
    i = 0
    while i < len(args):
        arg = args[i]
        i += 1
        if raw or not arg.startswith("-"):
            positional.append(arg)
        elif arg == "--json" and takes_json:
            as_json = True
        elif takes_format and (arg == "--format" or arg.startswith("--format=")):
            if arg == "--format":
                if i >= len(args):
                    raise Usage("option --format needs a value")
                fmt = args[i]
                i += 1
            else:
                fmt = arg[len("--format="):]
            if fmt not in ("text", "csv", "json"):
                raise Usage("bad value for --format: %r (text, csv or json)" % fmt)
        else:
            raise Usage("unknown option %s" % arg)
    if not low <= len(positional) <= high:
        raise Usage("wrong number of arguments for %s" % name)
    when = None
    if name in ("receive", "ship"):
        when = parse_date_text(positional[0])
    elif name == "fulfil":
        when = parse_date_text(positional[1])
    if name in ("receive", "ship", "fulfil") and when is None:
        raise Usage("bad date %r" % positional[0 if name != "fulfil" else 1])
    return name, directory, positional, as_json, fmt, when


# ----------------------------------------------------------------------- files


def _read_files(directory, names):
    base = directory if directory is not None else os.curdir
    if not os.path.isdir(base):
        raise Unreadable("%s: not a directory" % base)
    texts = {}
    raw = {}
    for name in names:
        path = os.path.join(base, name)
        try:
            with open(path, "rb") as handle:
                data = handle.read()
        except FileNotFoundError:
            if name == CATALOG:
                raise Unreadable("%s: file not found" % name)
            data = b""
        except OSError as exc:
            raise Unreadable("%s: %s" % (name, exc.strerror or exc))
        try:
            texts[name] = data.decode("utf-8")
        except UnicodeDecodeError:
            raise Unreadable("%s: not valid UTF-8" % name)
        raw[name] = data
    return base, texts, raw


def _parse_files(texts):
    data = {}
    try:
        name = CATALOG
        data["catalog"] = parse_catalog(texts[CATALOG])
        if MOVEMENTS in texts:
            name = MOVEMENTS
            data["movements"] = parse_movements(texts[MOVEMENTS], data["catalog"])
        if ORDERS in texts:
            name = ORDERS
            data["orders"] = parse_orders(texts[ORDERS], data["catalog"])
    except ParseError as exc:
        raise Refused("%s: %s" % (name, exc))
    return data


def _append(base, raw_existing, text):
    prefix = b"\n" if raw_existing and not raw_existing.endswith(b"\n") else b""
    try:
        with open(os.path.join(base, MOVEMENTS), "ab") as handle:
            handle.write(prefix + text.encode("utf-8"))
    except OSError as exc:
        raise Unreadable("%s: %s" % (MOVEMENTS, exc.strerror or exc))


# -------------------------------------------------------------------- commands


def _find_order(data, name):
    wanted = name.upper()
    for order in data["orders"]:
        if order.id == wanted:
            return order
    raise Refused("unknown order %s" % name)


def _cmd_stock(data, as_json):
    levels = shelves.stock_levels(data["catalog"], data["movements"])
    rows = []
    for sku in sorted(data["catalog"]):
        product = data["catalog"][sku]
        rows.append((sku, product.name, levels[sku], shelves.status(levels[sku], product.reorder)))
    if as_json:
        return _json([{"sku": s, "name": n, "onhand": o, "status": st} for s, n, o, st in rows])
    return _lines("%s %d %s %s" % (s_, o, st, n) for s_, n, o, st in rows)


def _cmd_low(data, as_json):
    levels = shelves.stock_levels(data["catalog"], data["movements"])
    rows = []
    for sku in sorted(data["catalog"]):
        product = data["catalog"][sku]
        if shelves.status(levels[sku], product.reorder) != "ok":
            rows.append((sku, levels[sku], product.reorder, shelves.buy_quantity(levels[sku], product.reorder)))
    if as_json:
        return _json([{"sku": s, "onhand": o, "reorder": r, "buy": b} for s, o, r, b in rows])
    return _lines("%s %d %d %d" % row for row in rows)


def _cmd_history(data, as_json, args):
    sku = args[0].upper()
    if sku not in data["catalog"]:
        raise Refused("unknown SKU %s" % args[0])
    rows = shelves.history(sku, data["movements"])
    if as_json:
        return _json(
            [
                {"date": m.date.isoformat(), "delta": "%+d" % m.quantity, "balance": b, "note": m.note}
                for m, b in rows
            ]
        )
    return _lines(
        "%s %+d %d" % (m.date.isoformat(), m.quantity, b) + (" " + m.note if m.note else "") for m, b in rows
    )


def _cmd_move(name, data, args, when, base, raw_movements):
    sku = args[1].upper()
    if sku not in data["catalog"]:
        raise Refused("unknown SKU %s" % args[1])
    qty_text = args[2]
    if not (qty_text.isascii() and qty_text.isdigit()):
        raise Refused("bad quantity %r (a whole number of one or more)" % qty_text)
    try:
        quantity = to_int(qty_text, 0, "quantity")
    except ParseError:
        raise Refused("quantity %r is too large" % qty_text[:20])
    if quantity < 1:
        raise Refused("bad quantity %r (a whole number of one or more)" % qty_text)
    note = args[3].strip() if len(args) == 4 else ""
    if "\n" in note or "\r" in note:
        raise Refused("a note may not contain a line break")
    signed = quantity if name == "receive" else -quantity
    move = Movement(when, sku, signed, note)
    if shelves.breaks_stock(data["movements"], move):
        raise Refused("%s %d of %s on %s would take the stock below zero" % (name, quantity, sku, args[0]))
    line = shelves.format_movement(when, sku, signed, note)
    _append(base, raw_movements, line + "\n")
    return line + "\n"


def _quote_text(quote, prefix=""):
    rows = ["%s%s %s %s" % (prefix, quote.order, quote.date.isoformat(), quote.customer)]
    for ln in quote.lines:
        rows.append(
            "%s %d %s %s %s %s"
            % (ln.sku, ln.quantity, money(ln.unit), money(ln.gross), money(ln.discount), money(ln.net))
        )
    rows.append("subtotal " + money(quote.subtotal))
    rows.append("order discount " + money(quote.order_discount))
    rows.append("tax " + money(quote.tax))
    rows.append("total " + money(quote.total))
    return _lines(rows)


def _quote_json(quote):
    return {
        "order": quote.order,
        "date": quote.date.isoformat(),
        "customer": quote.customer,
        "lines": [
            {
                "sku": ln.sku,
                "quantity": ln.quantity,
                "unit": money(ln.unit),
                "gross": money(ln.gross),
                "discount": money(ln.discount),
                "net": money(ln.net),
            }
            for ln in quote.lines
        ],
        "subtotal": money(quote.subtotal),
        "order_discount": money(quote.order_discount),
        "tax": money(quote.tax),
        "total": money(quote.total),
    }


def _cmd_quote(data, as_json, args):
    quote = price_order(_find_order(data, args[0]), data["catalog"])
    return _json(_quote_json(quote)) if as_json else _quote_text(quote)


def _cmd_invoice(data, as_json, args):
    order = _find_order(data, args[0])
    shipped = orders_mod.invoice_order(order, orders_mod.shipped_index(data["movements"]))
    if shipped is None:
        raise Refused("nothing has shipped for %s" % order.id)
    quote = price_order(shipped, data["catalog"])
    return _json(_quote_json(quote)) if as_json else _quote_text(quote, "invoice ")


def _cmd_fulfil(data, args, when, base, raw_movements):
    order = _find_order(data, args[0])
    if when < order.date:
        raise Refused("%s is dated %s; cannot fulfil on %s" % (order.id, order.date.isoformat(), args[1]))
    index = orders_mod.shipped_index(data["movements"])
    sent = {sku: s for sku, _, s in orders_mod.shipped_lines(order, index)}
    plan = orders_mod.plan_fulfilment(order, data["movements"], when, index)
    added = [shelves.format_movement(when, sku, -n, "order " + order.id) for sku, _, n in plan if n > 0]
    rows = []
    after = []
    for (sku, owed, n), (_, qty) in zip(plan, order.lines):
        rows.append("%s shipped %d backordered %d" % (sku, n, owed - n))
        after.append((sku, qty, sent[sku] + n))
    rows.append("status " + orders_mod.status_of(after))
    if added:
        _append(base, raw_movements, "".join(line + "\n" for line in added))
    return _lines(rows)


def _cmd_report(data, fmt):
    rows = orders_mod.report_rows(data["orders"], data["catalog"], data["movements"])
    for row in rows:
        row["quoted"] = money(row["quoted"])
        row["invoiced"] = money(row["invoiced"])
    if fmt == "json":
        return _json(rows)
    if fmt == "csv":
        keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(keys)
        for row in rows:
            writer.writerow([row[k] for k in keys])
        return buffer.getvalue()
    return _lines(
        "%s %s %s %s %d/%d %s %s"
        % (r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
        for r in rows
    )


def _run(argv):
    name, directory, args, as_json, fmt, when = _parse_command_line(argv)
    files = COMMANDS[name][0]
    base, texts, raw = _read_files(directory, files)
    data = _parse_files(texts)
    data.setdefault("movements", [])
    data.setdefault("orders", [])
    if name == "stock":
        return _cmd_stock(data, as_json)
    if name == "low":
        return _cmd_low(data, as_json)
    if name == "history":
        return _cmd_history(data, as_json, args)
    if name in ("receive", "ship"):
        return _cmd_move(name, data, args, when, base, raw[MOVEMENTS])
    if name == "quote":
        return _cmd_quote(data, as_json, args)
    if name == "fulfil":
        return _cmd_fulfil(data, args, when, base, raw[MOVEMENTS])
    if name == "invoice":
        return _cmd_invoice(data, as_json, args)
    return _cmd_report(data, fmt)


# ------------------------------------------------------------------------ main


def _silence_stdout():
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def _emit(text):
    if not text:
        return 0
    try:
        sys.stdout.write(text)
        sys.stdout.flush()
    except BrokenPipeError:
        _silence_stdout()
    except OSError as exc:
        _silence_stdout()
        print("stockroom: cannot write output: %s" % (exc.strerror or exc), file=sys.stderr)
        return 2
    return 0


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    try:
        reconfigure = sys.stdout.reconfigure
    except AttributeError:
        reconfigure = None
    if reconfigure is not None:
        try:
            reconfigure(encoding="utf-8")
        except (ValueError, OSError):
            pass
    try:
        out = _run(list(argv))
    except Usage as exc:
        print("stockroom: %s\n%s" % (exc, USAGE), file=sys.stderr)
        return 2
    except Unreadable as exc:
        print("stockroom: %s" % exc, file=sys.stderr)
        return 2
    except Refused as exc:
        print("stockroom: %s" % exc, file=sys.stderr)
        return 1
    return _emit(out)

"""Parsers for the three text files, and the error they raise."""

import re
from dataclasses import dataclass
from datetime import date as _date
from decimal import ROUND_HALF_UP, Context, Decimal
from typing import Dict, List, Tuple

MONEY_CONTEXT = Context(prec=1000000, rounding=ROUND_HALF_UP)
CENT = Decimal("0.01")
TAX_RATES = {"standard": Decimal("0.20"), "reduced": Decimal("0.05"), "zero": Decimal("0")}

# Python refuses to turn very long digit strings into ints; no real shop needs them.
MAX_DIGITS = 1000

_SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_PRICE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,2})?")
_UINT_RE = re.compile(r"[0-9]+")
_QTY_RE = re.compile(r"[+-]?[0-9]+")
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_ORDER_RE = re.compile(r"[Ss][Oo]-[0-9]+")
_SEP_RE = re.compile(r"[ \t]+")


class ParseError(ValueError):
    """A mistake in one line of a data file."""

    def __init__(self, line: int, reason: str):
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str


@dataclass(frozen=True)
class Movement:
    date: _date
    sku: str
    quantity: int
    note: str


@dataclass(frozen=True)
class Order:
    id: str
    date: _date
    customer: str
    lines: List[Tuple[str, int]]


def iter_lines(text: str):
    """Yield (1-based line number, line) for every line that is neither blank nor a comment."""
    if text.startswith("﻿"):
        text = text[1:]
    for number, raw in enumerate(text.split("\n"), 1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        yield number, raw


def to_int(digits: str, line: int, what: str) -> int:
    if len(digits.lstrip("+-")) > MAX_DIGITS:
        raise ParseError(line, "%s is too large" % what)
    return int(digits)


def parse_date_text(text: str):
    """Return a date for a real YYYY-MM-DD, else None."""
    if not _DATE_RE.fullmatch(text):
        return None
    try:
        return _date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        return None


def parse_catalog(text: str) -> Dict[str, Product]:
    catalog = {}  # type: Dict[str, Product]
    for number, raw in iter_lines(text):
        fields = [f.strip() for f in raw.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(number, "expected 4 or 5 fields separated by '|', found %d" % len(fields))
        sku, name, price, reorder = fields[:4]
        if not _SKU_RE.fullmatch(sku):
            raise ParseError(number, "bad SKU %r" % sku)
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if not name:
            raise ParseError(number, "empty name")
        if not _PRICE_RE.fullmatch(price):
            raise ParseError(number, "bad price %r" % price)
        value = Decimal(price).quantize(CENT, context=MONEY_CONTEXT)
        if value < CENT:
            raise ParseError(number, "bad price %r (must be at least 0.01)" % price)
        if not _UINT_RE.fullmatch(reorder):
            raise ParseError(number, "bad reorder level %r" % reorder)
        level = to_int(reorder, number, "reorder level")
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower()
            if tax not in TAX_RATES:
                raise ParseError(number, "bad tax %r (standard, reduced or zero)" % fields[4])
        catalog[sku] = Product(sku, name, value, level, tax)
    return catalog


def first_negative(movements) -> int:
    """Index (in the given list) of the movement that first takes a SKU below zero, or -1.

    Movements count in date order; same-day movements keep their list order.
    """
    balance = {}  # type: Dict[str, int]
    for index in sorted(range(len(movements)), key=lambda i: movements[i].date):
        move = movements[index]
        total = balance.get(move.sku, 0) + move.quantity
        if total < 0:
            return index
        balance[move.sku] = total
    return -1


def parse_movements(text: str, catalog) -> List[Movement]:
    movements = []  # type: List[Movement]
    lines = []  # type: List[int]
    for number, raw in iter_lines(text):
        parts = _SEP_RE.split(raw.strip(), maxsplit=3)
        if len(parts) < 3:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        when = parse_date_text(parts[0])
        if when is None:
            raise ParseError(number, "bad date %r" % parts[0])
        sku = parts[1].upper()
        if not _SKU_RE.fullmatch(parts[1]) or sku not in catalog:
            raise ParseError(number, "unknown SKU %r" % parts[1])
        if not _QTY_RE.fullmatch(parts[2]):
            raise ParseError(number, "bad quantity %r" % parts[2])
        quantity = to_int(parts[2], number, "quantity")
        if quantity == 0:
            raise ParseError(number, "quantity may not be zero")
        note = parts[3].strip() if len(parts) == 4 else ""
        movements.append(Movement(when, sku, quantity, note))
        lines.append(number)
    bad = first_negative(movements)
    if bad >= 0:
        raise ParseError(lines[bad], "stock of %s would go below zero" % movements[bad].sku)
    return movements


def parse_orders(text: str, catalog) -> List[Order]:
    orders = []  # type: List[Order]
    seen = set()
    for number, raw in iter_lines(text):
        parts = _SEP_RE.split(raw.strip())
        if len(parts) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES, found %d fields" % len(parts))
        order_id, when_text, customer, spec = parts
        if not _ORDER_RE.fullmatch(order_id):
            raise ParseError(number, "bad order number %r" % order_id)
        order_id = order_id.upper()
        if order_id in seen:
            raise ParseError(number, "duplicate order %s" % order_id)
        when = parse_date_text(when_text)
        if when is None:
            raise ParseError(number, "bad date %r" % when_text)
        lines = []  # type: List[Tuple[str, int]]
        used = set()
        for pair in spec.split(","):
            sku, star, qty = pair.partition("*")
            if not star or not _SKU_RE.fullmatch(sku) or not _UINT_RE.fullmatch(qty):
                raise ParseError(number, "bad order line %r (expected SKU*QUANTITY)" % pair)
            sku = sku.upper()
            if sku not in catalog:
                raise ParseError(number, "unknown SKU %r" % pair.partition("*")[0])
            if sku in used:
                raise ParseError(number, "SKU %s appears twice" % sku)
            quantity = to_int(qty, number, "quantity")
            if quantity < 1:
                raise ParseError(number, "quantity must be at least 1 in %r" % pair)
            used.add(sku)
            lines.append((sku, quantity))
        seen.add(order_id)
        orders.append(Order(order_id, when, customer, lines))
    return orders
"""Stock levels, low-stock reporting, history and movement validation."""

from datetime import date as _date
from typing import Dict, List, Tuple

from .parsing import Movement, first_negative


def in_date_order(movements) -> List[Movement]:
    """Movements in the order they count: by date, same-day movements in list order."""
    return sorted(movements, key=lambda m: m.date)


def stock_levels(catalog, movements) -> Dict[str, int]:
    levels = {sku: 0 for sku in catalog}
    for move in movements:
        if move.sku in levels:
            levels[move.sku] += move.quantity
    return levels


def status(onhand: int, reorder: int) -> str:
    if onhand == 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def buy_quantity(onhand: int, reorder: int) -> int:
    return max(1, 2 * reorder - onhand)


def history(sku: str, movements) -> List[Tuple[Movement, int]]:
    """The movements of one SKU in counting order, each with the balance after it."""
    balance = 0
    rows = []
    for move in in_date_order(movements):
        if move.sku == sku:
            balance += move.quantity
            rows.append((move, balance))
    return rows


def breaks_stock(movements, new: Movement) -> bool:
    """True when appending `new` to the end of `movements` takes any stock below zero."""
    return first_negative(list(movements) + [new]) >= 0


def format_movement(date: _date, sku: str, quantity: int, note: str) -> str:
    line = "%s %s %+d" % (date.isoformat(), sku, quantity)
    return line + " " + note if note else line
"""What has shipped for an order, fulfilment planning, status and report rows."""

from typing import Dict, List, Tuple

from .parsing import Order
from .pricing import ZERO, price_order
from .shelves import in_date_order


def shipped_index(movements) -> Dict[Tuple[str, str], int]:
    """Total units sent out, keyed by (note, sku), over negative movements."""
    index = {}  # type: Dict[Tuple[str, str], int]
    for move in movements:
        if move.quantity < 0:
            key = (move.note, move.sku)
            index[key] = index.get(key, 0) - move.quantity
    return index


def order_note(order) -> str:
    return "order " + order.id.upper()


def shipped_lines(order, index) -> List[Tuple[str, int, int]]:
    """(sku, ordered, shipped so far capped at ordered) for each order line."""
    note = order_note(order)
    return [(sku, qty, min(qty, index.get((note, sku), 0))) for sku, qty in order.lines]


def status_of(rows) -> str:
    owed = sum(qty - sent for _, qty, sent in rows)
    sent = sum(sent for _, _, sent in rows)
    if owed == 0:
        return "complete"
    if sent == 0:
        return "open"
    return "partial"


def plan_fulfilment(order, movements, on, index) -> List[Tuple[str, int, int]]:
    """(sku, owed, to ship on `on`) per order line."""
    ordered = in_date_order(movements)
    plan = []
    for sku, qty, sent in shipped_lines(order, index):
        owed = qty - sent
        balance = 0
        upto = 0
        later = None
        for move in ordered:
            if move.sku != sku:
                continue
            balance += move.quantity
            if move.date <= on:
                upto = balance
            elif later is None or balance < later:
                later = balance
        room = upto if later is None else min(upto, later)
        plan.append((sku, owed, max(0, min(owed, room))))
    return plan


def invoice_order(order, index):
    """The order cut down to what has shipped, or None when nothing has."""
    lines = [(sku, sent) for sku, _, sent in shipped_lines(order, index) if sent > 0]
    if not lines:
        return None
    return Order(order.id, order.date, order.customer, lines)


def _number_key(order_id: str):
    digits = order_id[3:].lstrip("0")
    return (len(digits), digits)


def report_rows(orders, catalog, movements) -> List[dict]:
    index = shipped_index(movements)
    rows = []
    for order in sorted(orders, key=lambda o: (o.date, _number_key(o.id), o.id)):
        lines = shipped_lines(order, index)
        invoice = invoice_order(order, index)
        rows.append(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "status": status_of(lines),
                "ordered": sum(qty for _, qty, _ in lines),
                "shipped": sum(sent for _, _, sent in lines),
                "quoted": price_order(order, catalog).total,
                "invoiced": price_order(invoice, catalog).total if invoice else ZERO,
            }
        )
    return rows
"""Exact-to-the-penny pricing of an order."""

from dataclasses import dataclass
from datetime import date as _date
from decimal import Decimal
from typing import List

from .parsing import CENT, MONEY_CONTEXT, TAX_RATES

ZERO = Decimal("0.00")
_ORDER_DISCOUNT_FROM = Decimal("500.00")
_ORDER_DISCOUNT_RATE = Decimal("0.03")


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass(frozen=True)
class Quote:
    order: str
    date: _date
    customer: str
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def _round(value: Decimal) -> Decimal:
    return value.quantize(CENT, context=MONEY_CONTEXT)


def _pennies(value: Decimal) -> int:
    return int(value.scaleb(2, context=MONEY_CONTEXT))


def _negative(value: Decimal) -> Decimal:
    """-value as a 2-place Decimal, never negative zero."""
    return -value if value else ZERO


def _share_out(pennies: int, nets: List[int]) -> List[int]:
    """Share `pennies` over lines in proportion to `nets`, rounding down, leftovers to biggest remainders."""
    total = sum(nets)
    if pennies == 0 or total == 0:
        return [0] * len(nets)
    shares = [pennies * n // total for n in nets]
    remainders = [pennies * n % total for n in nets]
    left = pennies - sum(shares)
    by_remainder = sorted(range(len(nets)), key=lambda i: (-remainders[i], i))
    for i in by_remainder[:left]:
        shares[i] += 1
    return shares


def price_order(order, catalog) -> Quote:
    ctx = MONEY_CONTEXT
    lines = []
    for sku, quantity in order.lines:
        product = catalog[sku]
        gross = _round(ctx.multiply(Decimal(quantity), product.price))
        rate = Decimal("0.10") if quantity >= 50 else Decimal("0.05") if quantity >= 10 else Decimal(0)
        discount = _negative(_round(ctx.multiply(gross, rate)))
        lines.append(QuoteLine(sku, quantity, product.price, gross, discount, ctx.add(gross, discount)))
    subtotal = ZERO
    for ln in lines:
        subtotal = ctx.add(subtotal, ln.net)
    order_discount = ZERO
    if subtotal >= _ORDER_DISCOUNT_FROM:
        order_discount = _negative(_round(ctx.multiply(subtotal, _ORDER_DISCOUNT_RATE)))
    nets = [_pennies(ln.net) for ln in lines]
    shares = _share_out(-_pennies(order_discount), nets)
    tax = ZERO
    for ln, share in zip(lines, shares):
        taxable = ctx.subtract(ln.net, Decimal(share).scaleb(-2, context=ctx))
        tax = ctx.add(tax, _round(ctx.multiply(taxable, TAX_RATES[catalog[ln.sku].tax])))
    total = _round(ctx.add(ctx.add(subtotal, order_discount), tax))
    return Quote(order.id, order.date, order.customer, lines, subtotal, order_discount, _round(tax), total)


def money(value: Decimal) -> str:
    """Two-place text, never '-0.00'."""
    value = _round(value)
    return format(value if value else ZERO, "f")
